import sys, json, collections
sys.path.insert(0, '/Users/leungvw/.codex/skills/ccdi-federation-ai-copilot/scripts')
from ccdi_client import read_only_get
base='https://federation.ccdi.cancer.gov/api/v1/'
pages=[]
subjects=[]
source_page_counts=[]
errors=[]
for page in range(1,4):
    res=read_only_get(base, '/subject', {'sex':'F','page':page,'per_page':10}, 30, 1)
    payload=res.get('payload')
    page_info={'page':page,'ok':res.get('ok'),'status':res.get('status'),'url':res.get('url'),'errors':res.get('errors') or [],'sources':0,'subjects':0,'node_errors':[]}
    if not res.get('ok'):
        errors.append({'page':page,'errors':res.get('errors')})
        pages.append(page_info)
        break
    if not isinstance(payload, list):
        errors.append({'page':page,'errors':['unexpected payload type '+type(payload).__name__]})
        pages.append(page_info)
        break
    page_info['sources']=len(payload)
    for node in payload:
        source=node.get('source') if isinstance(node,dict) else 'UNKNOWN'
        data=node.get('data') if isinstance(node,dict) else None
        if not isinstance(data,list):
            data=[]
        summary=(node.get('summary') or {}) if isinstance(node,dict) else {}
        counts=(summary.get('counts') or {}) if isinstance(summary,dict) else {}
        node_error=None
        for key in ('errors','error','message'):
            if isinstance(node,dict) and node.get(key):
                node_error={key:node.get(key)}
                break
        if node_error:
            page_info['node_errors'].append({'source':source, **node_error})
        source_page_counts.append({'page':page,'source':source,'data_count':len(data),'summary_current':counts.get('current'),'summary_all':counts.get('all')})
        page_info['subjects']+=len(data)
        for subj in data:
            if isinstance(subj,dict):
                subj['_source']=source
                subj['_page']=page
                subjects.append(subj)
    pages.append(page_info)
    # continue to max 3 as requested/default; no early stop while any source returned full page
    if page_info['subjects'] == 0:
        break

def val(x):
    if isinstance(x, dict) and 'value' in x:
        return val(x['value'])
    if isinstance(x, list):
        return [val(i) for i in x]
    return x

def first_values(md, field):
    v = md.get(field) if isinstance(md,dict) else None
    vv=val(v)
    if isinstance(vv, list):
        return [str(i) for i in vv if i is not None]
    if vv is None:
